    def longest_repeated_substring(s):
        def suffix_array(s):
            return sorted(range(len(s)), key=lambda i: s[i:])

        def lcp(s, sa):
            n = len(sa)
            rank = [0] * n
            for i, suffix in enumerate(sa):
                rank[suffix] = i
            lcp = [0] * n
            h = 0
            for i in range(n):
                if rank[i] > 0:
                    j = sa[rank[i] - 1]
                    while i + h < n and j + h < n and s[i + h] == s[j + h]:
                        h += 1
                    lcp[rank[i]] = h
                    if h > 0:
                        h -= 1
            return lcp

        sa = suffix_array(s)
        lcp_values = lcp(s, sa)
        max_len = 0
        for i in range(1, len(lcp_values)):
            if lcp_values[i] > max_len and sa[i] + lcp_values[i] <= len(s) and sa[i - 1] + lcp_values[i] <= len(s):
                max_len = lcp_values[i]
        return max_len

    result = longest_repeated_substring(s)
